@app.route('/login', methods=['POST'])
def login():
    # ... 校验通过 ...
    nxt = request.args.get('next', '/')
    # 关键：只允许本站内跳转，防开放重定向
    if not nxt.startswith('/'):
        nxt = '/'
    return redirect(nxt)

@app.route('/pay/return')
def pay_return():
    order_id = request.args.get('order_id')
    # 同步回跳只做展示：主动查一次支付平台确认
    result = alipay.api_trade_query(out_trade_no=order_id)
    if result.get('trade_status') == 'TRADE_SUCCESS':
        return render_template('pay_success.html', order=order_id)
    # 没确认就别写“成功”，展示处理中
    return render_template('pay_pending.html', order=order_id)
    # 注意：不要在这里把订单置为已支付！

@app.route('/pay/notify', methods=['POST'])
def pay_notify():
    data = request.form.to_dict()
    # 1. 验签：签名不对直接拒绝
    if not alipay.verify(data, data.pop('sign')):
        return 'fail'
    order_id = data['out_trade_no']
    # 2. 幂等：处理过的订单直接返回成功
    if order_paid(order_id):
        return 'success'
    # 3. 金额二次核对，更新订单并发货
    if data['total_amount'] == str(order_amount(order_id)):
        mark_paid(order_id)
    return 'success'  # 告诉支付平台别再重发

