const GEO = { CN: '/zh-cn', US: '/en-us', JP: '/ja-jp' };

app.use((req, res, next) => {
  // 用户手动选过就尊重选择
  if (req.cookies.locale) return next();
  // 否则按 IP 归属地 / 浏览器语言判断
  const country = geoip.lookup(req.ip)?.country || 'US';
  const lang = req.acceptsLanguages('zh', 'en', 'ja');
  const target = GEO[country] || (lang === 'zh' ? '/zh-cn' : '/en-us');
  if (!req.path.startsWith(target)) return res.redirect(302, target + req.path);
  next();
});
